LOCK TABLES `playerbot_zone_populations` WRITE;
/*!40000 ALTER TABLE `playerbot_zone_populations` DISABLE KEYS */;
/*!40000 ALTER TABLE `playerbot_zone_populations` ENABLE KEYS */;
